(40, 1, '2018-01-28 18:02:39', '2018-01-28 15:02:39', '[gallery columns=\"2\" link=\"none\" size=\"large\" ids=\"739,738\"]\r\n<p style=\"padding-left: 30px;\">[su_button url=\"http://video360-v-moskve.ru/category/sdelat-photo-interyera/\" style=\"flat\" background=\"#e63fc7\" size=\"11\"]Лайфхаки фото[/su_button]                [su_button url=\"http://video360-v-moskve.ru/category/kak-snyat-video360/\" style=\"flat\" background=\"#24ceb9\" size=\"11\"]Лайфхаки видео 360[/su_button]</p>', 'Портфолио', '', 'publish', 'closed', 'closed', '', '%d0%bf%d0%be%d1%80%d1%82%d1%84%d0%be%d0%bb%d0%b8%d0%be', '', '', '2018-01-30 13:19:13', '2018-01-30 10:19:13', '', 0, 'http://video360-v-moskve.ru/?page_id=40', 0, 'page', '', 0),
