}s:9:\"acf-field\";a:3:{s:5:\"label\";s:6:\"Fields\";s:4:\"icon\";s:20:\"dashicons-admin-page\";s:12:\"capabilities\";a:1:{i:0;s:14:\"manage_options\";}}s:18:\"wpcf7_contact_form\";a:3:{s:5:\"label\";s:13:\"Contact Forms\";s:4:\"icon\";s:20:\"dashicons-admin-post\";s:12:\"capabilities\";a:1:{i:0;s:24:\"wpcf7_edit_contact_forms\";}}}s:10:\"taxonomies\";a:3:{s:5:\"label\";s:10:\"Taxonomies\";s:4:\"icon\";s:0:\"\";s:12:\"capabilities\";a:8:{i:0;s:17:\"manage_categories\";i:1;s:15:\"edit_categories\";i:2;s:17:\"delete_categories\";i:3;s:17:\"assign_categories\";i:4;s:16:\"manage_post_tags\";i:5;s:14:\"edit_post_tags\";i:6;s:16:\"delete_post_tags\";i:7;s:16:\"assign_post_tags\";}}s:10:\"appearance\";a:3:{s:5:\"label\";s:10:\"Appearance\";s:4:\"icon\";s:26:\"dashicons-admin-appearance\";s:12:\"capabilities\";a:6:{i:0;s:13:\"delete_themes\";i:1;s:18:\"edit_theme_options\";i:2;s:11:\"edit_themes\";i:3;s:14:\"install_themes\";i:4;s:13:\"switch_themes\";i:5;s:13:\"update_themes\";}}s:7:\"plugins\";a:3:{s:5:\"label\";s:7:\"Plugins\";s:4:\"icon\";s:23:\"dashicons-admin-plugins\";s:12:\"capabilities\";a:5:{i:0;s:16:\"activate_plugins\";i:1;s:14:\"delete_plugins\";i:2;s:12:\"edit_plugins\";i:3;s:15:\"install_plugins\";i:4;s:14:\"update_plugins\";}}s:5:\"users\";a:3:{s:5:\"label\";s:5:\"Users\";s:4:\"icon\";s:21:\"dashicons-admin-users\";s:12:\"capabilities\";a:11:{i:0;s:9:\"add_users\";i:1;s:12:\"create_roles\";i:2;s:12:\"create_users\";i:3;s:12:\"delete_roles\";i:4;s:12:\"delete_users\";i:5;s:10:\"edit_roles\";i:6;s:10:\"edit_users\";i:7;s:10:\"list_roles\";i:8;s:10:\"list_users\";i:9;s:13:\"promote_users\";i:10;s:12:\"remove_users\";}}s:6:\"custom\";a:3:{s:5:\"label\";s:6:\"Custom\";s:4:\"icon\";s:0:\"\";s:12:\"capabilities\";a:1:{i:0;s:10:\"copy_posts\";}}}', 'yes'),
