(11312, 811, '_additional_information_banners_blok_4', 'field_5b17c589b33bd'),
(11243, 811, 'additional_information_banners_blok_3', ''),
(11244, 811, 'additional_information_banners_blok_4_title', 'Сервис по работе с клиентами'),
(11245, 811, 'additional_information_banners_blok_4_img', '302'),
(11246, 811, 'additional_information_banners_blok_4_descr', '<strong>Служба предложений и замечаний</strong>\r\nЕсли у вас есть какие-либо вопросы к качеству сервиса,\r\nили предложения по улучшению нашей работы, пишитеWhatsApp +7(985)100-56-88 / +7(985)100-54-57 почта nakvartirerf@gmail.com'),
(11311, 811, '_additional_information_banners_blok_4_descr', 'field_5b17c589b33c0'),
